(() => {
'use strict';
const C=window.C,e=C.esc,b=C.btn,i=C.icon;
const nav=[
 ['analysis','分析','spark','analyze'],['tasks','分析会话','clock','analyze'],['reports','报告空间','folder','assets'],['plugins','插件','code','assets'],['boards','看板','chart','assets'],['automations','定时任务','clock','automations'],['review','待我决定','check','review'],['scenarios','场景探索','grid','analyze'],
 ['admin-overview','控制总览','chart','admin-overview'],['data','数据与语义','database','data'],['capabilities','Agent 与能力','code','capabilities'],['runs','运行与调度','play','runs'],['quality','质量与发布','check','quality'],['security','安全与审计','shield','security'],['memory','记忆与产物','book','memory'],['organization','组织设置','users','organization']
];
const alias={home:'analysis',assets:'reports',artifacts:'reports',dashboards:'boards',console:'admin-overview',members:'organization',connections:'data',metrics:'data',audit:'security',operations:'runs',evaluations:'quality',releases:'quality',settings:'organization'};
C.route=()=>{let r;try{r=decodeURIComponent(location.hash.slice(1)||'analysis');}catch{r='analysis';}return alias[r]||r;};
C.go=route=>{route=alias[route]||route;if(C.route()===route)C.render();else location.hash=route;C.closeNavigation?.();};
const assetAllowed=a=>C.can('assets')&&(C.state.role!=='manager'||(a.contract?.region||a.region||'华东')==='华东');
const scope=()=>C.state.role==='manager'?'华东大区 · 授权渠道':C.state.role==='operator'||C.state.role==='auditor'?'运行元数据 · 业务内容隐藏':'中国业务 · 已授权数据';
function shell(route){return C.navigationHTML(route,nav.find(n=>n[0]===route)?.[1]||'分析工作台',scope());}
function head(kicker,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${actions}</div>`;}
const sparkline=()=>`<svg class="mini-chart" viewBox="0 0 400 90" role="img" aria-label="渠道贡献由上周72万元降至本周61万元"><path d="M0 70H400M0 35H400" stroke="#d6e0cd" stroke-dasharray="3 4"/><path d="M0 35 40 30 80 37 120 23 160 31 200 29 240 47 280 43 320 62 360 65 400 73" fill="none" stroke="#245941" stroke-width="2.3"/><path d="M0 35 40 30 80 37 120 23 160 31 200 29 240 47 280 43 320 62 360 65 400 73V90H0Z" fill="#8ead7830"/></svg>`;
function home(){return `<div class="home"><div class="home-intro"><h1>每个好问题，<span>都有迹可循。</span></h1><p>从一个经营问题开始，让数据带你看清下一步。</p></div><form id="composer-form" data-action="ask"><div class="composer"><label class="sr-only" for="question">你想了解什么经营问题？</label><textarea id="question" placeholder="本月销售增长了，为什么渠道贡献没有跟上？" maxlength="2000">${e(C.state.draft)}</textarea>${C.state.attachments.length?`<div class="attachment-list">${C.state.attachments.map(x=>`<span class="data-chip">${i('file')} ${e(x.name)} · ${x.rows} 行</span>`).join('')}${b('移除','clear-files','','ghost')}</div>`:''}<div class="composer-footer"><div class="composer-tools">${b(i('plus'),'attach','aria-label="添加 CSV 文件或引用上下文"','ghost icon-btn')}<select id="analysis-mode" aria-label="分析深度"><option>自动选择分析路径</option><option>快速回答</option><option>深度分析</option></select><span class="scope-chip">${i('database')} ${e(scope())}</span></div><button class="btn primary submit" type="submit" aria-label="开始分析">${i('arrow')}</button></div></div></form><div class="prompt-chips">${[['S01','上周经营表现'],['S05','解释指标变化'],['S07','预测未来销量'],['S03','分析一份文件']].map(([s,t])=>`<button class="prompt-chip" data-go="scenario/${s}">${i(s==='S03'?'file':'chart')}${t}</button>`).join('')}</div><div class="section-title"><h2>今天，值得多看一步</h2><a href="#scenarios">探索全部场景 ${i('arrow')}</a></div><div class="home-grid"><article class="signal-panel"><div class="eyebrow">经营信号 / 01</div><h2>销售在增长，<br>渠道贡献却收窄了。</h2><p>华东本周净销售额增长 8.2%，渠道贡献下降 15.3%。从折扣、结构与费用展开检查。</p><div class="signal-meta"><strong>−15.3<small>%</small></strong><span>渠道贡献环比<br>10.12 — 10.18</span></div>${sparkline()}${b('沿着这个问题分析 '+i('arrow'),'navigate','data-route="scenario/S05"','ghost')}</article><div class="panel"><div class="panel-head"><h2>让分析继续发生</h2>${C.badge('2 项待关注','warning')}</div><div class="task-note"><h3>跑鞋库存充足，热门尺码仍缺货</h3><p>R100 黑色 42 码 · 华东 18 家门店</p>${b('查看尺码分布 '+i('arrow'),'navigate','data-route="scenario/S02"','ghost')}</div><div class="task-note"><h3>周报已生成，等待确认接收范围</h3><p>经营管理组 · 报告 V3 · 今日 09:00</p>${b('查看发布请求 '+i('arrow'),'navigate','data-route="review"','ghost')}</div><div style="margin-top:22px;font-size:10px;color:var(--muted)">${i('shield')} 数据与动作始终遵循当前授权范围</div></div></div><section class="home-recent"><div class="section-title"><h2>最近的分析</h2><a href="#tasks">全部会话 ${i('arrow')}</a></div>${C.conversations().slice(0,3).map(r=>`<a class="recent-row" href="#chat/${e(r.taskId)}"><span class="recent-icon">${i('file')}</span><div><h3>${e(C.conversationTitle(r))}</h3><p>${e(C.conversationTopic(r))} · ${e(r.region)}</p></div>${C.badge(r.phase==='completed'?'已完成':r.phase==='ready'?'准备就绪':'进行中',r.phase==='completed'?'success':'warning')}<time>${new Date(C.conversationTime(r)).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})}</time></a>`).join('')}</section></div>`;}
function scenarios(){const filter=(C.state.scenarioFilter||'').toLowerCase();const rows=(C.scenarios||[]).filter(x=>JSON.stringify(x).toLowerCase().includes(filter));return head('SCENARIO LIBRARY','从问题，到适合的分析路径','12 类场景共享任务、证据与产物；每一种分析都有自己的完成标准。')+`<div class="toolbar"><label class="field">搜索场景<input class="search-input" id="scenario-search" data-action="scenario-filter" placeholder="例如：预测、退款、因果" value="${e(C.state.scenarioFilter||'')}"></label><span class="muted small">${rows.length} 个场景</span></div><div class="scenario-grid">${rows.map(s=>`<a href="#scenario/${s.id}" class="scenario-card"><span class="scenario-num">${s.id} / ANALYSIS</span><h2>${e(s.title)}</h2><p>${e(s.prompt||s.description)}</p><span class="card-foot"><span>${e(s.tag||'查看分析与产物')}</span>${i('arrow')}</span></a>`).join('')}</div>`;}
function tasks(){
 const rows=C.conversations();
 return head('ANALYSIS / CONVERSATIONS','全部分析会话','每个问题独立保存。打开会话可查看完整对话、运行记录与当前产物，并继续追问。',b(i('plus')+' 新建分析','new-chat','','primary'))+C.table(['分析会话','主题','状态','操作'],rows.length?rows.map(r=>[e(C.conversationTitle(r)),e(C.conversationTopic(r)),C.badge(r.phase),`<a class="btn" href="#chat/${e(r.taskId)}">打开会话</a>`]):[['还没有发起分析','—','准备就绪','<a class="btn" href="#analysis">新建分析</a>']]);
}
function assets(){let rows=C.state.artifacts.filter(assetAllowed).filter(x=>C.state.assetFilter==='all'||(x.type||'').includes(C.state.assetFilter));return head('REPORT SPACE','报告空间','将分析结果沉淀为可复用的报告与产物，保留版本、证据与传播状态。',b(i('search')+' 搜索资产','search'))+`<div class="tabs">${[['all','全部产物'],['报告','报告'],['图表','图表'],['数据','数据集']].map(([v,t])=>`<button class="tab ${C.state.assetFilter===v?'active':''}" data-action="asset-filter" data-value="${v}">${t}</button>`).join('')}</div>${rows.length?`<div class="grid-3">${rows.map((a,n)=>`<article class="card asset-card"><div class="asset-preview"><div class="eyebrow">${e(a.type)} / V${e(a.version)}</div><div class="bars">${[40,65,54,83,72,50,35,60].map((v,j)=>`<i style="height:${(v+n*9)%80+15}%"></i>`).join('')}</div></div><div class="asset-meta">${C.badge(a.verification||'待验证',a.verification==='通过'?'success':'warning')}${C.badge(a.publication||'草稿')}</div><h2>${e(a.title)}</h2><p>${e(a.updated||'刚刚')} · ${e(a.source||'合成经营数据')}</p><div class="asset-actions">${b('打开产物','asset-open',`data-id="${e(a.id)}"`,'primary')}${b(i('more'),'asset-open',`data-id="${e(a.id)}" aria-label="${e(a.title)}的版本与操作"`,'ghost icon-btn')}</div></article>`).join('')}</div>`:'<div class="empty">当前分类暂无资产。完成分析后可保存产物。</div>'}`;}
function assetOpen(id){const a=C.state.artifacts.find(x=>x.id===id);if(!a)return;if(!assetAllowed(a)){C.toast('该产物超出当前授权范围。');return;}C.activeAsset=id;C.modal(a.title,`<div class="toolbar">${C.badge(a.type)}${C.badge('V'+a.version,'info')}<span class="muted small">${e(a.source||'合成经营数据 · 当前运行')}</span></div><div class="ledger">${[['计算',a.status],['验证',a.verification||'未验证'],['采纳',a.adoption||'待决定'],['发布',a.publication||'草稿'],['新鲜度',a.freshness||'当前有效']].map(([k,v])=>`<div>${k}<strong>${e(v)}</strong></div>`).join('')}</div><h3>结论与证据</h3><p>${e(a.note||a.summary||'请查看此产物的关联分析、数据来源和验证记录。')}</p><details><summary>数据口径、依赖与版本</summary><p>方法：${e(a.method||'见关联分析的方法记录')}。数据来源：${e(a.source||'合成演示数据')}。范围：${e(a.contract?JSON.stringify(a.contract):a.region||scope())}。</p><p>当前版本 V${e(a.version)}；${e(a.edited?'存在人工编辑，已保留原版本':'无人工编辑')}。历史快照为演示记录。</p>${b('查看关联分析','asset-scenario')}</details><div class="toolbar">${b('编辑文字','asset-edit')}${b('复算','asset-recompute')}${b('刷新数据','asset-refresh')}${b('重新分析','asset-scenario')}${b('采纳此版本','asset-adopt')}</div>${a.publication==='已发布'?'<div class="notice">内部链接已发布。撤回链接会停止后续访问，已下载副本不自动收回。</div>':''}`,`${C.can('export')?b(i('download')+' 导出摘要','asset-export'):b('导出需单独权限','denied','','secondary')}${a.publication==='已发布'?b('撤回链接','asset-revoke','','danger'):b('发布给团队','asset-publish','','primary')}`);}
function automations(){return head('SCHEDULED TASKS','定时任务','固定刷新保持口径与模板；重新分析允许修订假设与方法。',b(i('plus')+' 创建定时任务','automation-new','','primary'))+`<div class="grid-2"><div class="panel"><div class="eyebrow">DATA READINESS</div><h2>数据就绪后，再生成本期报告。</h2><p class="muted small">抖音经营汇总延迟 2 小时。系统已暂停相关周报生成，其他数据就绪的任务继续运行。</p>${C.badge('1 个数据窗口等待中','warning')}</div><div class="panel"><div class="eyebrow">SIGNAL / RECOVERY</div><h2>热门尺码缺货率回落</h2><p class="muted small">同一异常在 6 小时冷却窗口内归并。最近一次调查保留恢复记录。</p><a class="btn" href="#scenario/S11">查看异常调查 ${i('arrow')}</a></div></div><div class="section-title"><h2>我的定时任务</h2><span class="muted small">北京时间 · Asia/Shanghai</span></div>`+C.table(['名称 / 版本','运行方式','范围与周期','接收范围','状态','操作'],C.state.automations.map(a=>[`${e(a.name)}<small class="muted"> · V${a.version}</small>`,e(a.type),`${e(a.scope)}<br><small>${e(a.frequency)}</small>`,e(a.receiver),C.badge(a.status,a.status==='运行中'?'success':'warning'),`${b(a.status==='运行中'?'暂停':'恢复','automation-toggle',`data-id="${a.id}"`)} ${b('运行记录','automation-detail',`data-id="${a.id}"`)}`]));}
function review(){return head('HUMAN DECISIONS','每个决定，都有明确的对象','澄清、计划对齐、执行授权、结果采纳和发布授权分别记录。')+`<div class="stack">${C.state.decisions.map(d=>`<article class="panel"><div class="panel-head"><div>${C.badge(d.kind,'info')}<h2 style="margin-top:12px">${e(d.title)}</h2></div>${C.badge(d.status,d.status==='待处理'?'warning':'success')}</div><p class="muted small">${e(d.scope)} · 申请人：Compass · 责任人：林知远</p>${d.status==='待处理'?b('查看证据与选项','decision-open',`data-id="${d.id}"`):`<p class="small">${e(d.note||'决定已保存，可在审计记录中查看。')}</p>`}</article>`).join('')}</div>`;}
function design(){return head('COMPASS / DESIGN LANGUAGE','安静地呈现，清楚地行动。','设计体系、场景入口与原型边界集中于此，供产品评审和后续开发使用。')+`<div class="grid-2"><section class="panel"><div class="eyebrow">01 / COLOR</div><h2>自然的底色，精确的状态</h2><div class="swatches">${[['画布','#f8f9f6'],['表面','#ffffff'],['墨绿','#1c5145'],['正文','#202b27'],['点缀','#dceab8']].map(([t,c])=>`<div><div class="swatch" style="background:${c}"></div><small>${c}</small><p class="small">${t}</p></div>`).join('')}</div><div class="toolbar">${C.badge('验证通过','success')}${C.badge('等待决定','warning')}${C.badge('权限受阻','danger')}${C.badge('执行中','info')}</div></section><section class="panel"><div class="eyebrow">02 / TYPE & SPACE</div><h2 style="font-family:'Songti SC',serif;font-size:30px">清晰，比喧闹更有力量。</h2><p>标题建立层级，正文解释问题，等宽数字保持可比性。</p><div class="mono">¥ 2,846,320.00　+8.2%　V3</div><p class="muted small" style="margin-top:18px">4 / 8 / 12 / 16 / 24 / 32 / 48 px<br>界面圆角 8–12 px；输入框 15 px；动效 140 / 220 ms。</p></section></div><section class="panel" style="margin-top:18px"><div class="eyebrow">03 / INTERACTION</div><h2>让操作的后果可以预期</h2><div class="toolbar">${b('主要操作','design-demo','','primary')}${b('次要操作','design-demo')}${b('文字操作','design-demo','','ghost')}${b('撤销授权','design-demo','','danger')}${b('权限不足','denied','disabled')}</div><p class="muted small">键盘可达、可见焦点、弹窗焦点约束、Esc 关闭、减少动态效果、图表数据替代。移动端保持任务优先。</p></section><section class="panel" style="margin-top:18px"><div class="eyebrow">04 / PROTOTYPE MAP</div><h2>12 种任务，完整交互雏形</h2><p class="muted small">场景页包含独立任务契约、运行控制、证据、产物以及状态演练入口。所有数值为合成示例；未连接模型、企业数据库、登录服务或外部投递。</p><div class="toolbar">${(C.scenarios||[]).map(s=>`<a class="btn" href="#scenario/${s.id}">${s.id} ${e(s.title)}</a>`).join('')}</div><p class="small">管理能力需切换到“企业管理员”；“组织设置”可调整各身份的功能授权。浏览器中的权限门禁用于体验演示，生产系统须由服务端落实。</p><div class="toolbar">${b('恢复全部演示状态','reset-confirm','','danger')}<a class="btn" href="../ui-ux-design-spec.md">查看设计规范</a><a class="btn" href="../../spec/PRD.md">查看完整 PRD</a></div></section>`;}
function denied(){return `<div class="no-access empty"><div class="empty-icon">${i('shield')}</div><h1 style="margin-top:20px">当前身份无法访问此功能</h1><p>请联系企业管理员调整功能授权与数据范围。已知链接同样受页面权限检查。</p>${b('回到可用工作台','safe-home','','primary')}</div>`;}
C.render=()=>{
 if(!C.isSignedIn()){C.renderLogin();return;}
 if(C.route()==='login')history.replaceState(null,'','#'+C.identityHome());
 document.body.classList.remove('login-page');
 C.initConversations();
 const route=C.route();let page;
 const entry=nav.find(n=>n[0]===route);
 const isChat=route.startsWith('chat/'),isScenario=route.startsWith('scenario/');
 const allowed=route==='design'||((isChat||isScenario)?C.can('analyze'):entry?C.can(entry[3]):false);
 if(!allowed)page=denied();
 else if(isChat){const r=C.activateConversation(route.slice(5)),stored=C.state.conversations[route.slice(5)];page=r?C.scenarioRender(r.id):stored?.deletedAt&&C.conversationAuthorized(stored)?'<div class="empty"><h1>这条会话已删除</h1><p>已保存到报告空间的产物会保留。最近删除的会话可在分析侧栏撤销。</p><a class="btn" href="#analysis">返回分析</a></div>':'<div class="empty"><h1>无法打开此分析会话</h1><p>会话可能不在当前浏览器，或超出当前身份的数据范围。</p><a class="btn" href="#analysis">返回分析</a></div>';}
 else if(isScenario){const id=route.split('/')[1];if(C.state.runs[id]?.deletedAt)delete C.state.runs[id];page=C.scenarioRender(id);const r=C.state.runs[id];if(r&&C.conversationVisible(r)){r.readAt=new Date().toISOString();r.unread=false;}}
 else page=({analysis:home,tasks,scenarios,reports:assets,plugins:()=>C.pluginsRender(),boards:()=>C.boardsRender(),automations,review,design}[route]||(()=>C.adminRender?.(route)||denied()))();
 C.save();
 document.getElementById('app').innerHTML=shell(route);
 document.getElementById('main').innerHTML=page;
 C.navigationDidRender();
 C.scenarioAfterRender?.();
 const chat=isChat&&C.state.conversations[route.slice(5)];
 document.title=`Compass · ${chat&&C.conversationVisible(chat)?C.conversationTitle(chat):nav.find(n=>n[0]===route)?.[1]||'分析工作台'}`;
};
C.handlers.navigate=el=>C.go(el.dataset.route);
C.handlers['new-chat']=()=>{C.state.draft='';C.state.navigation.query='';C.save();C.go('analysis');setTimeout(()=>document.getElementById('question')?.focus(),0);};
C.handlers['safe-home']=()=>C.go(nav.find(x=>C.can(x[3]))?.[0]||'design');
C.handlers['role-switch']=el=>{if(document.getElementById('modal').open)C.closeModal();if(!C.selectIdentity(el.value))return;if(!C.can('analyze')&&(C.route().startsWith('scenario/')||C.route().startsWith('chat/')))C.go(C.identityHome());else C.render();C.toast('体验身份已切换，功能与数据范围已重新计算。');};
C.handlers['scenario-filter']=el=>{C.state.scenarioFilter=el.value;C.render();};
C.handlers['task-history']=el=>{const r=C.visibleHistory?.[Number(el.dataset.index)];if(r?.taskId&&C.conversationVisible(r))C.go('chat/'+r.taskId);};
C.handlers['asset-filter']=el=>{C.state.assetFilter=el.dataset.value;C.save();C.render();};
C.handlers['asset-open']=el=>assetOpen(el.dataset.id);
C.handlers.denied=()=>C.toast('此操作需要独立授权，请联系企业管理员。');
C.handlers.ask=()=>{const q=document.getElementById('question').value.trim();if(!q){C.toast('先输入你想了解的经营问题。');document.getElementById('question').focus();return;}C.state.draft=q;C.save();let s='S05';if(/预测|未来/.test(q))s='S07';else if(/实验|A\/B/i.test(q))s='S08';else if(/因果|导致|涨价/.test(q))s='S09';else if(/文件|清洗|关联/.test(q)||C.state.attachments.length)s='S03';else if(/对账|差异|财务/.test(q))s='S04';else if(/报告|周报|日报/.test(q))s='S10';else if(/监控|预警/.test(q))s='S11';else if(/看板|应用/.test(q))s='S12';else if(/专题|半年|深度/.test(q)||document.getElementById('analysis-mode').value==='深度分析')s='S06';else if(/拆|渠道|尺码|新老客/.test(q))s='S02';else if(/多少|上周|是多少/.test(q)||document.getElementById('analysis-mode').value==='快速回答')s='S01';C.startConversation(s,q);};
C.handlers.attach=()=>C.modal('引用数据与上下文',`<p class="muted small">上传内容仅在本浏览器读取。CSV 将显示列名与行数；分析过程使用合成场景进行演示。</p><label class="field">选择 CSV 文件<input id="local-file" type="file" accept=".csv,text/csv" data-action="file-upload"></label><div class="notice">也可从已授权语义目录引用“净销售额 V3”或“R100 尺码库存”。</div>`,b('引用净销售额 V3','attach-metric','','primary'));
C.handlers['file-upload']=async el=>{const f=el.files[0];if(!f)return;if(f.size>2*1024*1024){C.toast('原型支持 2 MB 以内的 CSV，请缩小示例文件。');return;}if(!/\.csv$/i.test(f.name)){C.toast('请选择 CSV 文件。');return;}const text=await f.text();const lines=text.trim().split(/\r?\n/);C.state.attachments=[{name:f.name,rows:Math.max(0,lines.length-1),columns:lines[0].split(',').map(x=>x.slice(0,80))}];C.save();C.closeModal();C.render();C.toast('已读取文件结构，可进入清洗与关联场景。');};
C.handlers['attach-metric']=()=>{C.state.attachments=[{name:'净销售额 V3 · 认证指标',rows:7}];C.save();C.closeModal();C.render();};
C.handlers['clear-files']=()=>{C.state.attachments=[];C.save();C.render();};
C.handlers['asset-scenario']=()=>{const a=C.state.artifacts.find(x=>x.id===C.activeAsset);C.closeModal();C.go(a?.taskId&&C.state.conversations[a.taskId]?'chat/'+a.taskId:'scenario/'+(a?.scenario||'S05'));};
C.handlers['asset-edit']=()=>{const a=C.state.artifacts.find(x=>x.id===C.activeAsset);C.modal('编辑产物文字',`<p class="muted small">保存为新版本，保留原始计算与人工修改标记。修改事实结论后需要重新验证。</p><label class="field">结论<textarea id="asset-note">${e(a.note||a.summary||'')}</textarea></label>`,b('保存人工版本','asset-edit-save','','primary'));};
C.handlers['asset-edit-save']=()=>{const a=C.state.artifacts.find(x=>x.id===C.activeAsset);const note=document.getElementById('asset-note').value.trim();if(!note){C.toast('请填写结论文字。');return;}(a.history||=[]).push({version:a.version,note:a.note||a.summary||'原始结论'});a.note=note;a.version++;a.edited=true;a.verification='待验证';a.adoption='待决定';a.publication='草稿';C.log('编辑产物',a.id);C.save();C.closeModal();C.render();assetOpen(a.id);};
for(const [action,mode]of [['asset-recompute','复算'],['asset-refresh','刷新']])C.handlers[action]=()=>{const a=C.state.artifacts.find(x=>x.id===C.activeAsset);(a.history||=[]).push({version:a.version,note:a.note});a.version++;a.freshness='当前有效';a.verification='通过';a.status='完成';a.publication='草稿';a.adoption='待决定';a.updated='2026-10-20';a.lastOperation=mode+' · 保持当前方法与数据绑定';C.log(mode,a.id);C.save();C.closeModal();C.render();assetOpen(a.id);};
C.handlers['asset-adopt']=()=>{const a=C.state.artifacts.find(x=>x.id===C.activeAsset);if(a.verification!=='通过'){C.toast('请先完成验证，再采纳这个版本。');return;}a.adoption='已采纳';C.log('采纳版本',a.id+' V'+a.version);C.save();assetOpen(a.id);};
C.handlers['asset-export']=()=>{if(!C.can('export'))return C.handlers.denied();const a=C.state.artifacts.find(x=>x.id===C.activeAsset);C.download('Compass-'+a.title+'-V'+a.version+'.json',JSON.stringify({...a,disclaimer:'合成数据原型导出；不包含真实业务数据'},null,2),'application/json');C.log('导出资产摘要',a.id);C.toast('已导出此版本摘要。');};
C.handlers['asset-publish']=()=>{if(!C.can('publish'))return C.handlers.denied();const a=C.state.artifacts.find(x=>x.id===C.activeAsset);if(a.verification!=='通过'){C.toast('该版本尚未通过验证，暂不可发布。');return;}C.modal('确认发布对象与范围',`<p>将 <strong>${e(a.title)} V${a.version}</strong> 分享给指定内部组。新增受众不会继承底层明细权限。</p><label class="field">接收组<select id="asset-audience"><option>经营管理组 · 12 人</option><option>华东经营组 · 8 人</option></select></label><p class="muted small">此授权只绑定当前版本；后续版本需重新检查。</p>`,b('取消','close-modal')+b('授权发布此版本','asset-publish-confirm','','primary'));};
C.handlers['asset-publish-confirm']=()=>{if(!C.can('publish'))return C.handlers.denied();const a=C.state.artifacts.find(x=>x.id===C.activeAsset);a.publication='已发布';a.audience=document.getElementById('asset-audience').value;C.log('发布版本',a.id+' V'+a.version+' → '+a.audience);C.save();C.closeModal();C.render();assetOpen(a.id);};
C.handlers['asset-revoke']=()=>{if(!C.can('publish'))return C.handlers.denied();const a=C.state.artifacts.find(x=>x.id===C.activeAsset);a.publication='已撤回';C.log('撤回在线链接',a.id);C.save();C.closeModal();C.render();assetOpen(a.id);};
C.handlers['automation-toggle']=el=>{const a=C.state.automations.find(x=>x.id===el.dataset.id);a.status=a.status==='运行中'?'已暂停':'运行中';C.log('持续分析'+a.status,a.id);C.save();C.render();};
C.handlers['automation-new']=()=>C.modal('创建定时任务',`<label class="field">名称<input id="auto-name" placeholder="例如：华东经营日报" required></label><div class="grid-2"><label class="field">运行方式<select id="auto-type"><option>固定刷新</option><option>重新分析</option><option>主动监控</option></select></label><label class="field">频率<select id="auto-frequency"><option>每日 09:00</option><option>每周一 09:00</option><option>每小时</option></select></label></div><label class="field">接收范围<select id="auto-receiver"><option>仅自己</option><option>华东经营组</option></select></label><label class="check-line"><input type="checkbox" id="auto-approve">授权在当前数据范围与每日 ¥20 预算内持续执行</label><p id="auto-error" role="alert" style="color:var(--danger)"></p><p class="muted small">数据未到齐时等待；责任人失效时暂停；生成与投递分别记录。</p>`,b('创建并授权','automation-save','','primary'));
C.handlers['automation-save']=()=>{const name=document.getElementById('auto-name').value.trim();if(!name||!document.getElementById('auto-approve').checked){document.getElementById('auto-error').textContent='请填写名称，并确认持续授权范围。';return;}C.state.automations.push({id:'au'+Date.now(),name,type:document.getElementById('auto-type').value,frequency:document.getElementById('auto-frequency').value,receiver:document.getElementById('auto-receiver').value,scope:scope(),status:'运行中',version:1});C.save();C.closeModal();C.render();};
C.handlers['automation-detail']=el=>{const a=C.state.automations.find(x=>x.id===el.dataset.id);C.modal(a.name+' · 运行记录',C.table(['周期','数据就绪','分析状态','投递状态'],[['10月20日 09:00','等待抖音数据',C.badge('等待数据','warning'),'未投递'],['10月19日 09:00','已就绪',C.badge('完成','success'),'内部通知已送达 · 回执 R-019']])+`<p class="muted small" style="margin-top:16px">责任人：林知远；固定授权 V${a.version}；冷却 6 小时；单次预算 ¥5；连续失败 3 次升级给维护者。</p>`);};
C.handlers['decision-open']=el=>{C.activeDecision=el.dataset.id;const d=C.state.decisions.find(x=>x.id===C.activeDecision);C.modal(d.kind,`<h3>${e(d.title)}</h3><p>${e(d.scope)}</p><div class="notice">已完成查询与验证。此决定只影响当前申请对象，其他分析继续。</div><label class="field">决定说明<textarea id="decision-note" placeholder="可说明同意范围、修改条件或拒绝原因"></textarea></label><label class="field">授权选项<select id="decision-choice"><option value="approved">同意当前对象与范围</option><option value="partial">仅同意华东经营组</option><option value="rejected">拒绝申请</option></select></label>`,b('返回','close-modal')+b('记录决定','decision-save','','primary'));};
C.handlers['decision-save']=()=>{const d=C.state.decisions.find(x=>x.id===C.activeDecision);const choice=document.getElementById('decision-choice').value;if(d.kind==='发布授权'&&choice!=='rejected'&&!C.can('publish')){C.toast('当前身份没有发布授权权限，请由有权限的管理者处理。');return;}d.status=choice==='approved'?'已同意':choice==='partial'?'部分同意':'已拒绝';d.note=document.getElementById('decision-note').value||'仅作用于此申请的对象与范围。';C.log(d.kind+' '+d.status,d.id);C.save();C.closeModal();C.render();};
C.handlers.search=()=>C.modal('搜索当前授权内容',`<label class="field">关键词<input id="global-search" data-action="search-query" placeholder="搜索场景、产物或功能" autofocus></label><div id="search-results" class="stack"><p class="muted small">输入关键词后显示匹配结果。</p></div>`);
C.handlers['search-query']=el=>{const q=el.value.trim();const results=nav.filter(x=>C.can(x[3])&&x[1].includes(q)).map(x=>[x[1],x[0]]);if(C.can('analyze'))results.push(...C.conversations().filter(r=>C.conversationTitle(r).includes(q)).map(r=>[C.conversationTitle(r),'chat/'+r.taskId]));if(C.can('analyze'))results.push(...(C.scenarios||[]).filter(s=>s.title.includes(q)||s.prompt?.includes(q)).map(s=>[s.title,'scenario/'+s.id]));if(C.can('assets'))results.push(...C.state.artifacts.filter(assetAllowed).filter(a=>a.title.includes(q)).map(a=>[a.title,'reports']));document.getElementById('search-results').innerHTML=q?(results.map(([t,r])=>b(e(t)+' '+i('arrow'),'search-go',`data-route="${r}"`)).join('')||'<p class="muted">当前授权范围内无匹配结果。</p>'):'<p class="muted">请输入关键词。</p>';};
C.handlers['search-go']=el=>{C.closeModal();C.go(el.dataset.route);};
C.handlers.notifications=()=>C.modal('通知中心',`<div class="list-row"><div><h3>数据窗口延迟</h3><p class="muted small">抖音经营汇总晚到，相关任务正在等待。</p></div>${C.badge('等待','warning')}</div><div class="list-row"><div><h3>有一份报告需要复核</h3><p class="muted small">华东渠道贡献诊断 V3</p></div>${C.badge('待决定','info')}</div>`,b('前往待我决定','notification-go','','primary'));
C.handlers['notification-go']=()=>{C.closeModal();C.go('review');};
C.handlers.profile=()=>C.modal('个人设置',`<div class="profile-line"><span class="avatar">${e(C.currentAccount().name[0])}</span><div><h3>${e(C.currentAccount().name)}</h3><p class="muted small">${e(C.roles[C.state.role])} · ${e(scope())}</p></div></div><label class="field">分析偏好<select id="preference"><option>优先给结论，按需展开过程</option><option>展开计划与方法摘要</option></select></label><p class="muted small">偏好仅属于当前体验身份，不授予额外的数据或动作权限。</p>`,b(i('logout')+' 注销当前账号','logout','','danger profile-logout')+b('保存偏好','preference-save','','primary'));
C.handlers['preference-save']=()=>{C.state.preferences||={};C.state.preferences[C.state.role]=document.getElementById('preference').value;C.save();C.closeModal();C.toast('个人分析偏好已保存。');};
C.handlers['design-demo']=()=>C.modal('组件交互示例','<p>焦点进入弹窗，Tab 在弹窗内移动，Esc 关闭后回到触发控件。</p><label class="field">示例名称<input placeholder="输入一个名称"></label>');
C.handlers['reset-confirm']=()=>C.modal('恢复演示状态','<p>清除当前浏览器的任务、产物修改、权限配置和其他演示状态。源文件保持不变。</p>',b('取消','close-modal')+b('恢复初始状态','reset-state','','danger'));
C.handlers['reset-state']=()=>{localStorage.removeItem(C.storageKey);location.href=location.pathname+'#analysis';location.reload();};
document.addEventListener('click',event=>{if(event.target.closest('.skip-link')){event.preventDefault();document.getElementById('main').focus();return;}const go=event.target.closest('[data-go]');if(go){C.go(go.dataset.go);return;}const el=event.target.closest('[data-action]');if(!el||['INPUT','SELECT','TEXTAREA','FORM'].includes(el.tagName)||el.disabled)return;C.handlers[el.dataset.action]?.(el,event);});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('input[data-action],select[data-action],textarea[data-action]'))C.handlers[el.dataset.action]?.(el,event);});
document.addEventListener('input',event=>{if(event.target.id==='question'){C.state.draft=event.target.value;C.save();}if(event.target.id==='global-search')C.handlers['search-query'](event.target,event);});
document.addEventListener('submit',event=>{const form=event.target.closest('form[data-action]');if(form){event.preventDefault();C.handlers[form.dataset.action]?.(form,event);}});
document.addEventListener('keydown',event=>{if(event.target.id==='question'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();C.handlers.ask();}if(event.key==='Escape')document.body.classList.remove('menu-open');});
document.getElementById('modal').addEventListener('cancel',event=>{event.preventDefault();C.closeModal();});
window.addEventListener('hashchange',()=>{C.closeNavigation?.();C.render();window.scrollTo(0,0);document.getElementById('main')?.focus();});
C.render();
})();
